import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useSettings } from '../context/SettingsContext';

const navLinks = [
    { to: '/', label: 'Home' },
    { to: '/about', label: 'About Us' },
    { to: '/courses', label: 'Courses' },
    { to: '/services', label: 'Services' },
    { to: '/team', label: 'Team' },
    { to: '/portfolios', label: 'Portfolios' },
    { to: '/certificates', label: 'Certificates' },
    { to: '/contact', label: 'Contact' },
];

export default function Navbar() {
    const [scrolled, setScrolled] = useState(false);
    const [menuOpen, setMenuOpen] = useState(false);
    const { settings } = useSettings();
    const location = useLocation();

    useEffect(() => {
        const onScroll = () => setScrolled(window.scrollY > 20);
        window.addEventListener('scroll', onScroll);
        return () => window.removeEventListener('scroll', onScroll);
    }, []);

    useEffect(() => {
        setMenuOpen(false);
    }, [location]);

    return (
        <header
            style={{
                position: 'sticky',
                top: 0,
                zIndex: 900,
                background: scrolled ? 'rgba(11,15,25,0.92)' : 'rgba(11,15,25,0.6)',
                backdropFilter: 'blur(12px)',
                borderBottom: scrolled ? '1px solid rgba(148,163,184,0.15)' : 'none',
                transition: 'all 0.3s',
            }}
        >
            <div
                className="container"
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    height: 72,
                }}
            >
                <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <div
                        style={{
                            width: 38,
                            height: 38,
                            borderRadius: 10,
                            background: 'linear-gradient(135deg, #10B981, #F59E0B)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontWeight: 800,
                            color: '#04130d',
                            fontFamily: "'Plus Jakarta Sans', sans-serif",
                        }}
                    >
                        MA
                    </div>
                    <span style={{ fontWeight: 800, fontSize: '1.15rem', color: '#fff' }}>
                        {settings.companyName}
                    </span>
                </Link>

                <nav
                    className="nav-desktop"
                    style={{ display: 'flex', alignItems: 'center', gap: 4 }}
                >
                    {navLinks.map((l) => (
                        <Link
                            key={l.to}
                            to={l.to}
                            style={{
                                padding: '8px 14px',
                                borderRadius: 8,
                                fontSize: '0.92rem',
                                fontWeight: 500,
                                color:
                                    location.pathname === l.to ? '#10B981' : '#E2E8F0',
                                background:
                                    location.pathname === l.to
                                        ? 'rgba(16,185,129,0.1)'
                                        : 'transparent',
                            }}
                        >
                            {l.label}
                        </Link>
                    ))}
                    <Link
                        to="/admissions"
                        className="btn btn-primary"
                        style={{ marginLeft: 12 }}
                    >
                        Enroll Now
                    </Link>
                </nav>

                <button
                    className="nav-toggle"
                    onClick={() => setMenuOpen(!menuOpen)}
                    style={{
                        display: 'none',
                        background: 'transparent',
                        color: '#fff',
                        fontSize: '1.6rem',
                    }}
                    aria-label="Toggle menu"
                >
                    ☰
                </button>
            </div>

            {menuOpen && (
                <div
                    className="nav-mobile"
                    style={{
                        background: '#0F1525',
                        borderTop: '1px solid rgba(148,163,184,0.15)',
                        padding: '12px 24px 20px',
                    }}
                >
                    {navLinks.map((l) => (
                        <Link
                            key={l.to}
                            to={l.to}
                            style={{
                                display: 'block',
                                padding: '12px 8px',
                                color: location.pathname === l.to ? '#10B981' : '#E2E8F0',
                                borderBottom: '1px solid rgba(148,163,184,0.08)',
                            }}
                        >
                            {l.label}
                        </Link>
                    ))}
                    <Link
                        to="/admissions"
                        className="btn btn-primary"
                        style={{ marginTop: 14, width: '100%', justifyContent: 'center' }}
                    >
                        Enroll Now
                    </Link>
                </div>
            )}
        </header>
    );
}
